def xorQueries(arr: list[int], queries: list[list[int]]) -> list[int]:
    P = [0] * (len(arr) + 1)
    for i in range(len(arr)):
        P[i + 1] = P[i] ^ arr[i]
    return [P[r + 1] ^ P[l] for l, r in queries]

#include <vector>
using namespace std;

vector<int> xorQueries(vector<int>& arr, vector<vector<int>>& queries) {
    vector<int> P(arr.size() + 1, 0);
    for (int i = 0; i < arr.size(); i++) P[i + 1] = P[i] ^ arr[i];
    vector<int> res;
    for (auto& q : queries) {
        res.push_back(P[q[1] + 1] ^ P[q[0]]);
    }
    return res;
}

public class Solution {
    public int[] xorQueries(int[] arr, int[][] queries) {
        int[] P = new int[arr.length + 1];
        for (int i = 0; i < arr.length; i++) P[i + 1] = P[i] ^ arr[i];
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            res[i] = P[queries[i][1] + 1] ^ P[queries[i][0]];
        }
        return res;
    }
}

