int maxGcdAfterRemoval(vector<int>& arr) {
    int n = arr.size();
    if (n <= 1) return 0;
    vector<int> pref(n), suff(n);
    pref[0] = arr[0];
    for (int i = 1; i < n; i++) pref[i] = gcd(pref[i - 1], arr[i]);
    suff[n - 1] = arr[n - 1];
    for (int i = n - 2; i >= 0; i--) suff[i] = gcd(suff[i + 1], arr[i]);
    int maxGcd = max(suff[1], pref[n - 2]);
    for (int i = 1; i < n - 1; i++) {
        maxGcd = max(maxGcd, gcd(pref[i - 1], suff[i + 1]));
    }
    return maxGcd;
}

